const esc=value=>String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const time=value=>value?new Date(value).toLocaleString('zh-TW',{hour12:false}):'—';
export function matrixView(client){
  const job=client.selected,summary=job?.summary,coverage=summary?.coverage?.flowPasses||{},active=job&&['queued','running','cancelling'].includes(job.status);
  const rows=(summary?.attempts||[]).map(a=>`<tr><td>${esc(a.flow)}</td><td>${esc(a.round)}</td><td>${esc(a.status)}</td><td>${esc(a.exitCode??'—')}</td><td>${esc(a.error||'')}</td></tr>`).join('');
  return `<div class="page-heading"><div><p class="eyebrow">PHASE M · UNATTENDED MATRIX</p><h1>完整自動測試</h1><p>Web UI 啟動後由後端獨立執行；關閉分頁不會停止測試。每個流程三輪，保留過程與結果。</p></div><div class="actions"><button class="button secondary" data-matrix-refresh>↻ 更新</button><button class="button primary" data-matrix-start ${active||client.busy?'disabled':''}>▷ 啟動完整測試</button>${active?'<button class="button danger" data-matrix-cancel>取消測試</button>':''}</div></div>
  <section class="card"><div class="card-heading"><div><h2>覆蓋範圍</h2><p>GEPA canonical ledger 開／關 × profile smoke/full/bank × searchMode 省略/standard/explore × finalRepetitions 省略/1/2/3：72 種路徑（45 種有效、27 種預期拒絕）。LLM、規則 Skill 與 Python 修復另有 18 種選項組合。每條路徑都跑三輪。</p></div></div><p>另含 M1–M7 元件與完整驗收、Docker 隔離和 release 回歸測試。實際模型品質與 Windows GPU 穩定性需在目標機器另行驗證。</p><p>需要已安裝鎖定的 M 依賴；啟動後會自動建置 Docker evaluator image。準備或測試失敗都會保留第一個失敗點及未執行清單。</p></section>
  ${client.error?`<div class="error-banner spaced">${esc(client.error)}</div>`:''}
  <section class="card spaced"><div class="card-heading"><div><h2>測試工作</h2><p>${job?`${esc(job.id)} · ${esc(job.status)} · 開始 ${time(job.createdAt)} · 結束 ${time(job.finishedAt)}`:'尚無工作'}</p></div>${job?.archiveReady?`<a class="button secondary" href="/api/v1/tests/matrix/${encodeURIComponent(job.id)}/support" download>↓ 下載測試紀錄 ZIP</a>`:''}</div>
  ${job?`<p>GEPA 組態 ${esc(coverage.configurations||0)}/3 · 其他組態 ${esc(coverage['other-options']||0)}/3 · 元件 ${esc(coverage.components||0)}/3 · 驗收 ${esc(coverage.acceptance||0)}/3 · 結論 ${esc(summary?.status||job.status)}</p>${summary?.coverage?.workflowPasses?`<details><summary>各流程與資料／模型變體通過輪數</summary><ul>${Object.entries(summary.coverage.workflowPasses).map(([name,count])=>`<li>${esc(name)}：${esc(count)}/3</li>`).join('')}</ul></details>`:''}${job.error?`<p class="form-error">${esc(job.error)}</p>`:''}
  <div class="table-wrap"><table><thead><tr><th>流程</th><th>輪次</th><th>狀態</th><th>Exit code</th><th>原因</th></tr></thead><tbody>${rows||'<tr><td colspan="5">等待第一輪結束</td></tr>'}</tbody></table></div><details><summary>最近輸出</summary><pre class="live-output">${esc(job.logTail||'等待後端輸出')}</pre></details>`:'<p>按「啟動完整測試」，服務將建立獨立工作並持續記錄進度。</p>'}</section>
  <section class="card spaced"><div class="card-heading"><h2>近期工作</h2></div><div class="table-wrap"><table><thead><tr><th>ID</th><th>狀態</th><th>建立時間</th></tr></thead><tbody>${client.jobs.map(row=>`<tr><td><button class="button secondary" data-matrix-select="${esc(row.id)}">${esc(row.id)}</button></td><td>${esc(row.status)}</td><td>${time(row.createdAt)}</td></tr>`).join('')||'<tr><td colspan="3">尚無紀錄</td></tr>'}</tbody></table></div></section>`;
}
